# Example for nested if statements

number = 4

# if condition to check if number is b/n 0 and 9
if number in range(10):
    # if condition to check if the number is b/n 0 and 4
    if number in range(5):
        print("Number is between 0 and 4")
    # else statement
    else:
        print("Number is between 5 and 9")
# else statement
else:
    print("Number is greater than or equal to 10")

# pass statement in if condition

