Ctl-Opt DftActGrp(*NO) ;

// Procedure ProtoType
Dcl-PR TestSubProcedure Packed(1 : 0) ;
  pFirstParameter Char(10) Const ;
  pSecondParameter Char(10) Options(*NoPass) ;
  pThirdParameter Char(10) Options(*NoPass) ;
END-PR;

// Work Variable to hold number of parameters passed
Dcl-S wNumberOfParameters Packed(1 : 0) ;
Dcl-S wMandatoryParameter Char(10) Inz('MANDATORY') ;
Dcl-S wOptionalParameter Char(10) Inz('OPTIONAL') ;
Dcl-S wExtraParameter Char(10) Inz('EXTRA') ;

// Call Procedure with One Parameter
wNumberOfParameters = TestSubProcedure(wMandatoryParameter) ;
Dsply wNumberOfParameters ;

// Call Procedure with Two Parameters
wNumberOfParameters = TestSubProcedure(wMandatoryParameter : wOptionalParameter) ;
Dsply wNumberOfParameters ;

// Call Procedure with Three Parameters
wNumberOfParameters = TestSubProcedure(wMandatoryParameter : wOptionalParameter : wExtraParameter) ;
Dsply wNumberOfParameters ;

*InLr = *On ;

// Procedure
Dcl-Proc TestSubProcedure  ;

  Dcl-PI TestSubProcedure Packed(1 : 0) ;
    pFirstParameter Char(10) Const ;
    pSecondParameter Char(10) Options(*NoPass) ;
    pThirdParameter Char(10) Options(*NoPass) ;
  END-PI;

  Dcl-S wNumberOfParameters Packed(1 : 0) ;

  If %Parms = 1 ;
    wNumberOfParameters = 1 ;
  ElseIf %Parms = 2 ;
    wNumberOfParameters = 2 ;
  Else ;
    wNumberOfParameters = 3 ;
  EndIf;

  Return wNumberOfParameters ;

END-PROC;

// Procedure
Dcl-Proc TestSubProcedure  ;

  Dcl-PI TestSubProcedure Packed(1 : 0) RtnParm ;
    pFirstParameter Char(10) Const ;
    pSecondParameter Char(10) Options(*NoPass) ;
    pThirdParameter Char(10) Options(*NoPass) ;
  END-PI;

  Dcl-S wNumberOfParameters Packed(1 : 0) ;

  If %Parms = 2 ;
    wNumberOfParameters = 1 ;
  ElseIf %Parms = 3 ;
    wNumberOfParameters = 2 ;
  ElseIf %Parms = 4 ;
    wNumberOfParameters = 3 ;
  EndIf;

  Return wNumberOfParameters ;

END-PROC;

// Procedure
Dcl-Proc TestSubProcedure  ;

  Dcl-PI TestSubProcedure Packed(1 : 0) ;
    pFirstParameter Char(10) Const ;
    pSecondParameter Char(10) Options(*NoPass) ;
    pThirdParameter Char(10) Options(*NoPass) ;
  END-PI;

  Dcl-S wNumberOfParameters Packed(1 : 0) ;
  Dcl-S wParameterNumber Packed(1 : 0) ;

  wParameterNumber = %ParmNum(pFirstParameter) ;
  Dsply wParameterNumber ; // 1

  wParameterNumber = %ParmNum(pSecondParameter) ;
  Dsply wParameterNumber ; // 2

  wParameterNumber = %ParmNum(pThirdParameter) ;
  Dsply wParameterNumber ; // 3

  wNumberOfParameters = %Parms ;
  Return wNumberOfParameters ;

END-PROC;

// Procedure
Dcl-Proc TestSubProcedure  ;

  Dcl-PI TestSubProcedure Packed(1 : 0) RtnParm ;
    pFirstParameter Char(10) Const ;
    pSecondParameter Char(10) Options(*NoPass) ;
    pThirdParameter Char(10) Options(*NoPass) ;
  END-PI;

  Dcl-S wNumberOfParameters Packed(1 : 0) ;
  Dcl-S wParameterNumber Packed(1 : 0) ;

  wParameterNumber = %ParmNum(pFirstParameter) ;
  Dsply wParameterNumber ; // 2

  wParameterNumber = %ParmNum(pSecondParameter) ;
  Dsply wParameterNumber ; // 3

  wParameterNumber = %ParmNum(pThirdParameter) ;
  Dsply wParameterNumber ; // 4

  wNumberOfParameters = %Parms ;
  Return wNumberOfParameters ;

END-PROC;

