// Standalone variables to store the Date
Dcl-S wDate Date(*ISO) ;
Dcl-S wDateDMY Date(*DMY) ;

// Standalone variables to store Year, Month and Date
Dcl-S wYear Packed(4 : 0) ;
Dcl-S wMonth Packed(2 : 0) ;
Dcl-S wDay Packed(2 : 0) ;

// Move current date to Date field
wDate = %Date() ; // 2021-05-02
wDateDMY = %Date() ; // 02/05/21

// Extract Year from Date
wYear = %SubDt(wDate : *Y) ;
Dsply wYear ; // 2021

// Year returned would always be 4 digits
// irrespective of the date format used
wYear = %SubDt(wDateDMY : *Y) ;
Dsply wYear ; // 2021

// Extract Month from Date
// %Date() can also be used with %SubDt
wMonth = %SubDt(%Date() : *M) ;
Dsply wMonth ; // 05

// Extract Day from Date
// Date can also be specified directly
wDay = %SubDt(d'2021-05-02' : *D) ;
Dsply wDay ; // 02

*InLr = *On ;

**Free

// Standalone variables to store the Time
Dcl-S wTime Time ;

// Standalone variables to store Hours, Minutes and Seconds
Dcl-S wHours Packed(2 : 0) ;
Dcl-S wMinutes Packed(2 : 0) ;
Dcl-S wSeconds Packed(2 : 0) ;

// Move current time to Time field
wTime = %Time() ; // 23:08:10

// Extract Hours from Time
wHours = %SubDt(wTime : *HOURS) ;
Dsply wHours ; // 23

// Extract Minutes from Time
// %Time() can also be used with %SubDt
wMinutes = %SubDt(%Time() : *MN) ;
Dsply wMinutes ; // 08

// Extract Seconds from Time
// Date can also be specified directly
wSeconds = %SubDt(t'23.08.55' : *S) ;
Dsply wSeconds ; // 55

*InLr = *On ;

**Free

// Standalone variables to store the Timestamp
Dcl-S wTimeStamp TimeStamp ;

// Standalone variables to store Hours, Minutes and Seconds
Dcl-S wMilliSeconds Packed(6 : 0) ;
Dcl-S wSeconds Packed(8 : 6) ;

// Move current timestamp to Timestamp field
wTimeStamp = %TimeStamp() ; // 2021-05-02-23.24.50.990546

// Extract Milliseconds from Timestamp
wMilliSeconds = %SubDt(wTimeStamp : *MS) ;
Dsply wMilliSeconds ; // 990546

// Extract Seconds from TimeStamp
// Timestamp can also be specified directly
wSeconds = %SubDt(z'2021-05-02-23.24.50.990546' : *S : 6 : 4) ;
Dsply wSeconds ; // 50.990500

*InLr = *On ;
